-- Связки симптом - причина и причина - ремонт.
-- Производитель не ранжирует причины, поэтому likelihood остаётся значением по умолчанию (3).
-- Названия должны точно совпадать с 003: пропущенная связка проверяется тестом на «сирот».

INSERT IGNORE INTO symptom_causes (symptom_id, cause_id)
SELECT s.id, c.id
FROM (
    SELECT 'Кабина не реагирует на кнопки, нет сигнализации' AS s_title, 'Нет напряжения питания в цепях управления' AS c_title
    UNION ALL SELECT 'Неточная остановка: пол кабины выше или ниже порога более чем на 35 мм', 'Вытяжка тяговых канатов'
    UNION ALL SELECT 'Неточная остановка: пол кабины выше или ниже порога более чем на 35 мм', 'Масло на тормозном шкиве или накладках'
    UNION ALL SELECT 'Неточная остановка: пол кабины выше или ниже порога более чем на 35 мм', 'Износ накладок тормоза или тормозного диска'
    UNION ALL SELECT 'Неточная остановка: пол кабины выше или ниже порога более чем на 35 мм', 'Разрегулировка тормоза'
    UNION ALL SELECT 'Кабина остановилась между этажами во время движения', 'Сработал выключатель подвески кабины (разная вытяжка канатов)'
    UNION ALL SELECT 'Кабина остановилась между этажами во время движения', 'Сработал выключатель ВНУ натяжного устройства ограничителя скорости'
    UNION ALL SELECT 'Кабина остановилась между этажами во время движения', 'Отпирается замок двери шахты на проходе этажа (сбита отводка)'
    UNION ALL SELECT 'Двери не закрываются, привод дверей не включается', 'Не замкнулся контакт закрытия дверей или обрыв цепи'
    UNION ALL SELECT 'Двери закрылись, но кабина не трогается', 'Сбита регулировка или неисправен выключатель контроля закрытия дверей кабины'
    UNION ALL SELECT 'Двери закрылись, но кабина не трогается', 'Не запирается замок створок двери шахты'
    UNION ALL SELECT 'Двери закрылись, но кабина не трогается', 'Сбита регулировка блока контроля двери шахты'
    UNION ALL SELECT 'Двери непрерывно открываются и закрываются', 'Посторонний предмет между створками или на порогах'
    UNION ALL SELECT 'Створки дверей кабины не открываются на полный проём', 'Неверно установлен упор или кулачок открывания дверей кабины'
    UNION ALL SELECT 'Двери не реверсируются при помехе закрытию', 'Поломка выключателя реверса или обрыв его проводов'
    UNION ALL SELECT 'Двери кабины не закрываются после выхода пассажиров', 'Неисправен выключатель закрытия двери'
    UNION ALL SELECT 'Кабина на малой скорости проезжает мимо этажа', 'Неверно установлен шунт точной остановки этажа'
    UNION ALL SELECT 'Кабина самопроизвольно садится на ловители', 'Ослабла пружина ограничителя скорости'
    UNION ALL SELECT 'Кабина самопроизвольно садится на ловители', 'Ослаблено крепление башмаков кабины или износ вкладышей'
    UNION ALL SELECT 'При пуске лебёдка гудит, свет в кабине тускнеет, кабина стоит', 'Нет напряжения на фазе лебёдки или просадка сети'
    UNION ALL SELECT 'Сбои электропривода и автоматики при нажатии кнопок', 'Пробой изоляции на корпус или нарушена изоляция проводов'
    UNION ALL SELECT 'Остановка с ошибкой контроля тормоза или пускателя (УЛ 45, ПЧ E36)', 'Нет сигнала КТА или КТВ от микропереключателей тормоза'
    UNION ALL SELECT 'Остановка с ошибкой контроля тормоза или пускателя (УЛ 45, ПЧ E36)', 'Повреждён пускатель или контактор'
    UNION ALL SELECT 'Остановка с ошибкой контроля тормоза или пускателя (УЛ 45, ПЧ E36)', 'Неверно подключён контакт обратной связи пускателя или тормоза'
) AS l
JOIN symptoms s ON s.title = l.s_title
JOIN causes c ON c.title = l.c_title;

INSERT IGNORE INTO cause_fixes (cause_id, fix_id)
SELECT c.id, f.id
FROM (
    SELECT 'Нет напряжения питания в цепях управления' AS c_title, 'Проверить питание, заменить автомат или предохранитель' AS f_title
    UNION ALL SELECT 'Вытяжка тяговых канатов', 'Выровнять длину тяговых канатов'
    UNION ALL SELECT 'Масло на тормозном шкиве или накладках', 'Очистить тормозной шкив и накладки от масла'
    UNION ALL SELECT 'Износ накладок тормоза или тормозного диска', 'Заменить накладки тормоза или тормозной диск'
    UNION ALL SELECT 'Разрегулировка тормоза', 'Отрегулировать тормоз'
    UNION ALL SELECT 'Сработал выключатель подвески кабины (разная вытяжка канатов)', 'Выровнять длину тяговых канатов'
    UNION ALL SELECT 'Сработал выключатель ВНУ натяжного устройства ограничителя скорости', 'Укоротить канат ограничителя скорости'
    UNION ALL SELECT 'Отпирается замок двери шахты на проходе этажа (сбита отводка)', 'Отрегулировать отводку двери кабины и ролики замка'
    UNION ALL SELECT 'Не замкнулся контакт закрытия дверей или обрыв цепи', 'Проверить выключатель закрытия дверей, при необходимости заменить'
    UNION ALL SELECT 'Сбита регулировка или неисправен выключатель контроля закрытия дверей кабины', 'Проверить выключатель закрытия дверей, при необходимости заменить'
    UNION ALL SELECT 'Не запирается замок створок двери шахты', 'Отрегулировать замок створок двери шахты'
    UNION ALL SELECT 'Сбита регулировка блока контроля двери шахты', 'Отрегулировать блок контроля двери шахты'
    UNION ALL SELECT 'Посторонний предмет между створками или на порогах', 'Очистить пороги кабины и шахты'
    UNION ALL SELECT 'Неверно установлен упор или кулачок открывания дверей кабины', 'Отрегулировать упор или кулачок открывания дверей'
    UNION ALL SELECT 'Поломка выключателя реверса или обрыв его проводов', 'Проверить цепь реверса, при необходимости заменить выключатель'
    UNION ALL SELECT 'Неисправен выключатель закрытия двери', 'Проверить выключатель закрытия дверей, при необходимости заменить'
    UNION ALL SELECT 'Неверно установлен шунт точной остановки этажа', 'Отрегулировать положение шунта точной остановки'
    UNION ALL SELECT 'Ослабла пружина ограничителя скорости', 'Заменить ограничитель скорости или его пружину'
    UNION ALL SELECT 'Ослаблено крепление башмаков кабины или износ вкладышей', 'Подтянуть крепление башмаков, заменить вкладыши'
    UNION ALL SELECT 'Нет напряжения на фазе лебёдки или просадка сети', 'Измерить напряжение на фазах и восстановить питание лебёдки'
    UNION ALL SELECT 'Пробой изоляции на корпус или нарушена изоляция проводов', 'Проверить изоляцию и заземление, устранить пробой'
    UNION ALL SELECT 'Нет сигнала КТА или КТВ от микропереключателей тормоза', 'Проверить цепи обратной связи тормоза и пускателя'
    UNION ALL SELECT 'Повреждён пускатель или контактор', 'Проверить цепи обратной связи тормоза и пускателя'
    UNION ALL SELECT 'Неверно подключён контакт обратной связи пускателя или тормоза', 'Проверить цепи обратной связи тормоза и пускателя'
) AS l
JOIN causes c ON c.title = l.c_title
JOIN fixes f ON f.title = l.f_title;
